 navigationGoal=null;setRegion(state.position.region||'alp');path=[];marker.visible=false;pos.x=state.position.x;pos.z=state.position.z;inside=state.position.inside&&region==='alp';
 world.sync?.(state);if(blocked(pos.x,pos.z,world.colliders)){[pos.x,pos.z]=REGIONS[region].spawn;inside=false;}
 ({angle,zoom,overview,volume,soundEnabled,musicVolume,musicEnabled}=state.settings);if(state.settings.cameraRevision!==2){overview=false;zoom=1;state.settings.cameraRevision=2;}if(region==='alp'&&Math.abs(angle-.56)<.00001)angle=.25;player.g.visible=true;if(track!==(state.settings.radioTrack||0)){track=state.settings.radioTrack||0;music.src='assets/audio/'+playlist[track].file;}homePath=[];homeGoal=null;decorating=false;selectedFurniture=null;syncHome();if(inside)snapInteriorCamera();else if(INTERIOR_REGIONS.includes(region)||inBarn(pos,region==='alp')){player.g.position.set(pos.x,height(pos.x,pos.z),pos.z);snapInteriorCamera();}
 $('place').textContent=inside?'Ein warmes Plätzchen.':region==='alp'?'Da oben ist die Welt etwas ruhiger.':REGIONS[region].name;
 $('subtitle').textContent=inside?'Rucksack öffnen: lagern, rasten und herstellen.':REGIONS[region].text;const cp=state.climbing.checkpoint;if(cp){const result=startClimb(state,cp.route,{resume:true});if(result.ok){climb=result.session;climbHudKey='';document.body.classList.add('climbing');syncClimbHUD();}else{state.climbing.checkpoint=null;toast('Kletterstand nicht fortsetzbar. Du bist sicher am Einstieg. '+result.message);}}world.climbKit?.sync(climb);if(state.ski.active){ski=state.ski.active;skiKit=createSkiWorld(ski.level,player.g);document.body.classList.add('skiing');syncSkiHUD();}if(state.targets.active){targetRound=state.targets.active;targetNotice='';targetNoticeUntil=0;targetKit=createTargetWorld(targetRound.kind,player.g);targetKit.resize(innerWidth/innerHeight);document.body.classList.add('targeting');syncTargetHUD();}if(state.arcade.active){arcRound=state.arcade.active;document.body.classList.add('arcading');syncArcade();}syncAudio();updateNearest();updateQuest();
