function endClimbRuntime(success){const old=climb,result=finishClimb(state,old,success);if(!result.ok){toast(result.message);return;}climb=null;world.climbKit?.sync(null);pos.x=state.position.x;pos.z=state.position.z;restoreScene();save();if(success){dialog('<span class="eyebrow">KLETTERROUTE GESCHAFFT</span><h2 data-game-tone="success">✓ '+CLIMBS[old.route].name+'</h2><p>'+result.message+'</p><p>Bestwert: '+state.climbing.best[old.route]+' Punkte. Deine Aufgabenbelohnung wartet im Aufgabenbuch.</p><div class="actions"><button id="after-climb" class="primary">Weiter auf Entdeckungsreise</button><button id="climb-journal">Aufgaben ansehen</button></div>');$('after-climb').onclick=closeDialog;$('climb-journal').onclick=()=>panels.journal();}else toast(result.message);}
