function syncSkiHUD(){
 $('skihud').hidden=!ski;if(!ski)return;const level=SKI_LEVELS[ski.level],hits=ski.results.filter(Boolean).length;$('skiname').textContent='Sonnenalp-Slalom · '+level.name;$('skistats').textContent=hits+' Tore getroffen · '+ski.results.length+' / 12 passiert · '+ski.time.toFixed(1)+' s';$('skihint').textContent=ski.countdown>0?'Start in '+Math.ceil(ski.countdown)+' …':ski.done?'Im Ziel.':'Ziel: '+level.goal+' / 12 Tore · zwischen den Stangen durchfahren';skiKit?.sync(ski,state.environment);
}
function showSkiIntro(){captureState();dialog('<span class="eyebrow">SCHNEEFELD AUF DER SONNENALP</span><h2>Sonnenalp-Slalom</h2><p>Fahre zwischen den Stangen der zwölf Tore hindurch. Die Abfahrt läuft automatisch. Lenke mit A/D oder Pfeil links/rechts; S oder Pfeil runter bremst. Auf dem iPad hältst du die grossen Steuerknöpfe gedrückt.</p><p>Jede Runde kostet 8 Energie. Ski und Helm werden gestellt. Vor dem Start läuft ein Drei-Sekunden-Countdown. Du kannst pausieren, abbrechen und nach einem Neuladen fortsetzen. Der Lauf wird an jedem Tor, regelmässig und beim Verlassen gespeichert.</p><p>Jede Stufe zahlt nur beim ersten Erfolg eine Prämie. Wiederholungen verbessern deinen Bestwert. Verfehlte Tore kosten Punkte; du fährst trotzdem bis zum Ziel.</p><div class="item-grid">'+Object.entries(SKI_LEVELS).map(([id,l])=>'<article class="item-card"><h3>'+l.name+'</h3><p>'+l.goal+' von 12 Toren nötig · '+money(l.reward)+' einmalig</p><small>Bestwert: '+(state.ski.best[id]??'–')+' · '+state.ski.runs[id]+' Zielläufe'+(state.ski.completed.includes(id)?' · Prämie erhalten':'')+'</small><button data-ski="'+id+'" '+(state.energy<8?'disabled':'')+'>Abfahrt starten</button></article>').join('')+'</div>');for(const el of document.querySelectorAll('[data-ski]'))el.onclick=()=>{captureState();const r=startSki(state,el.dataset.ski);if(!r.ok){toast(r.message);return;}ski=state.ski.active;skiKit=createSkiWorld(ski.level,player.g);camera.position.set(0,6,12);document.body.classList.add('skiing');closeDialog();syncSkiHUD();save();};}
function pauseSki(){if(!ski)return;skiTouch.clear();dialog('<span class="eyebrow">SKI-PAUSE</span><h2>Durchatmen im Schnee</h2><p>Zeit, Tore und Bewegung stehen während der Pause still. Dein Lauf bleibt beim Neuladen erhalten. Abbrechen bringt dich ohne Prämie zum Start zurück.</p><div class="actions"><button id="ski-continue" class="primary">Weiterfahren</button><button id="ski-return">Lauf abbrechen</button><button id="ski-export">Spielstand herunterladen</button></div>');$('ski-continue').onclick=closeDialog;$('ski-return').onclick=()=>{abandonSki(state);endSkiRuntime();closeDialog();save();toast('Sicher am Slalomstart. Bestwerte bleiben erhalten.');};$('ski-export').onclick=downloadSave;save();}
