function finishSkiRuntime(){const r=finishSki(state,exchangeInventory);if(!r.ok){pauseSki();toast(r.message);return;}endSkiRuntime();save();dialog('<span class="eyebrow">SLALOM · '+SKI_LEVELS[r.level].name.toUpperCase()+'</span><h2 data-game-tone="'+(r.won?'success':'danger')+'">'+(r.won?'✓ ':'✕ ')+r.message+'</h2><p>'+r.hits+' von 12 Toren · '+r.score+' Punkte · '+r.time.toFixed(1)+' Sekunden</p><p>Bestwert: '+state.ski.best[r.level]+' Punkte. '+(r.reward?'Erste Erfolgsprämie: +'+money(r.reward)+'.':'Keine zusätzliche Geldprämie für diesen Lauf.')+'</p><div class="actions"><button id="ski-again" class="primary">Neue Runde wählen</button><button id="ski-leave">Zur Sonnenalp</button></div>');$('ski-again').onclick=showSkiIntro;$('ski-leave').onclick=closeDialog;}
const skiTouch=new Set();for(const [id,key]of [['ski-left','left'],['ski-right','right'],['ski-brake','brake']]){const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();if(!ski||paused)return;skiTouch.add(key);b.setPointerCapture?.(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>skiTouch.delete(key));} $('ski-pause').onclick=pauseSki;
function syncTargetHUD(){ $('targethud').hidden=!targetRound;if(!targetRound)return;const c=targetRound,d=TARGET_LEVELS[c.level];$('targetname').textContent=TARGET_NAMES[c.kind]+' · '+d.name;$('targetstats').textContent=c.score+' Punkte · '+c.hits+' / '+d.goal+' Treffer · '+c.ammo+' '+(c.kind==='snow'?'Bälle':'Schüsse')+' · '+Math.ceil(d.time-c.time)+' s · Schutzfehler '+c.fouls+' / 3';$('targethint').textContent=c.countdown>0?'Start in '+Math.ceil(c.countdown)+' …':targetNotice&&c.time<targetNoticeUntil?targetNotice:c.kind==='snow'?'Nur Hüte treffen. Holzschirme, Personen und Kinder abwarten.':'Spieltauben und Enten treffen. Weisse Türkentauben vorbeilassen.';targetKit?.sync(c);}
function showTargetIntro(kind){captureState();dialog('<span class="eyebrow">CHALLENGE IN DER BERGWELT</span><h2>'+TARGET_NAMES[kind]+'</h2><p>'+(kind==='snow'?'Triff nur Hüte und Mützen der Schneemänner und Holz-Rentierfigur. Körper zählen nicht. Getroffene Hüte kehren nach kurzer Zeit zurück. Holzschirme verdecken zeitweise ein Ziel. Personen und unbeteiligte Kinder nicht bewerfen.':'Ziele auf die vorbeifliegenden Spieltauben und Enten. Weisse Türkentauben sind mit GESCHÜTZT markiert: Lass sie vorbeifliegen. Getroffene Ziele erscheinen nach kurzer Zeit wieder.')+'</p><p>Treffer +10 Punkte. Daneben'+(kind==='snow'?' oder Holzschirm':'')+' −5. Geschütztes Ziel −20. Drei Schutzfehler beenden die Runde, auch wenn du vorher das Trefferziel erreicht hast.</p><p>Klick oder Tipp zielt und '+(kind==='snow'?'wirft':'schiesst')+'. Alternativ Fadenkreuz mit WASD/Pfeilen oder den Richtungsbuttons bewegen, mit E/Leertaste oder «Aktion» auslösen. Zwischen Aktionen liegt eine kurze Pause. Jeder neue Lauf kostet 5 Energie. Fortschritt wird automatisch gespeichert; Pause, Abbruch und Datei-Sicherung stehen bereit.</p><div class="item-grid">'+Object.entries(TARGET_LEVELS).map(([level,d])=>'<article class="item-card"><h3>'+d.name+'</h3><p>'+d.goal+' Treffer · '+d.ammo+' Versuche · '+d.time+' s</p><small>Bestwert: '+(state.targets[kind].best[level]??'–')+' · '+state.targets[kind].runs[level]+' Runden. Erste Erfolgsprämie '+money(d.reward)+(state.targets[kind].completed.includes(level)?' · bereits erhalten':'')+'.</small><button data-targetlevel="'+level+'" '+(state.energy<5?'disabled':'')+'>Starten</button></article>').join('')+'</div><small>Die Geldprämie gibt es pro Spiel und Stufe einmal. Danach spielst du um den Bestwert. Die Runde endet bei Zeitablauf oder verbrauchten Versuchen.</small>');for(const el of document.querySelectorAll('[data-targetlevel]'))el.onclick=()=>{captureState();const r=startTarget(state,kind,el.dataset.targetlevel);if(!r.ok){toast(r.message);return;}targetRound=state.targets.active;targetNotice='';targetNoticeUntil=0;targetKit=createTargetWorld(kind,player.g);targetKit.resize(innerWidth/innerHeight);document.body.classList.add('targeting');closeDialog();syncTargetHUD();save();};}
function endTargetRuntime(){targetKit?.dispose();targetKit=null;targetRound=null;targetTouch.clear();document.body.classList.remove('targeting');$('targethud').hidden=true;updateNearest();}
function pauseTarget(){if(!targetRound)return;dialog('<span class="eyebrow">CHALLENGE-PAUSE</span><h2>Alles steht still</h2><p>Zeit und Ziele bewegen sich während der Pause nicht. Du kannst den gespeicherten Stand nach einem Neuladen fortsetzen. Abbruch führt ohne Prämie zum Startplatz zurück.</p><div class="actions"><button id="target-continue" class="primary">Weiterspielen</button><button id="target-return">Abbrechen</button><button id="target-export">Spielstand herunterladen</button></div>');$('target-continue').onclick=closeDialog;$('target-return').onclick=()=>{state.targets.active=null;endTargetRuntime();closeDialog();save();};$('target-export').onclick=downloadSave;save();}
function finishTargetRuntime(){const r=finishTarget(state,exchangeInventory);if(!r.ok){pauseTarget();toast(r.message);return;}endTargetRuntime();save();dialog('<span class="eyebrow">'+TARGET_NAMES[r.kind].toUpperCase()+'</span><h2 data-game-tone="'+(r.won?'success':'danger')+'">'+(r.won?'✓ ':'✕ ')+(r.reason==='protected'?'Runde beendet · geschützte Ziele beachten':r.won?'Challenge geschafft!':'Noch eine Runde?')+'</h2><p>'+r.score+' Punkte · '+r.hits+' Treffer · '+r.misses+' Fehlversuche · '+r.fouls+' Schutzfehler · '+r.time.toFixed(1)+' s</p><p>Bestwert: '+state.targets[r.kind].best[r.level]+'. '+(r.reward?'Erste Erfolgsprämie: +'+money(r.reward)+'.':'Keine zusätzliche Prämie für diese Runde.')+'</p><div class="actions"><button id="target-again" class="primary">Neue Runde wählen</button><button id="target-leave">Zurück zur Bergwelt</button></div>');$('target-again').onclick=()=>showTargetIntro(r.kind);$('target-leave').onclick=closeDialog;}
function fireTarget(event=null){if(!targetRound||paused)return;if(event){const p=canvasPoint(canvas,event);if(!p)return;pointer.set(p.x,p.y);targetRound.aim.x=Math.max(-10,Math.min(10,pointer.x*(targetKit.camera.right)));targetRound.aim.y=Math.max(1,Math.min(12,7+pointer.y*targetKit.camera.top));}else{const v=new T.Vector3(targetRound.aim.x,targetRound.aim.y,0).project(targetKit.camera);pointer.set(v.x,v.y);}ray.setFromCamera(pointer,targetKit.camera);const hit=ray.intersectObjects(targetKit.pickable())[0],r=shootTarget(targetRound,hit?.object.userData.targetId||'miss');if(!r.ok)return;gameFeedback('targethint',r.type==='hit'?'success':'danger');targetNotice=r.message;targetNoticeUntil=targetRound.time+1.5;syncTargetHUD();save();tone(r.type==='hit'?700:170,.10,'sine',.06);if(targetRound.done)finishTargetRuntime();}
const targetTouch=new Set();for(const id of ['left','right','up','down']){const b=$('target-'+id);b.addEventListener('pointerdown',e=>{e.preventDefault();if(!targetRound||paused)return;targetTouch.add(id);b.setPointerCapture?.(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>targetTouch.delete(id));}$('target-fire').onclick=()=>fireTarget();$('target-pause').onclick=pauseTarget;
function syncArcade(){ $('arcadehud').hidden=!arcRound;$('arcade-board').hidden=!arcRound;if(!arcRound)return;$('arcadename').textContent=arcadeHeading(arcRound);$('arcadestats').textContent=arcadeStats(arcRound);$('arcade-board').innerHTML=arcadeBoard(arcRound);}
function showArcadeIntro(m=''){captureState();const s=state;dialog('<span class="eyebrow">MELANIES LADEN · RETRO-ECKE</span><h2>Gratis spielen. Bestwerte jagen.</h2><p>Melanie: «Zwüschet dure dörf mer au eifach chli spiele.»</p>'+(m?'<p class="panel-message" role="status">'+m+'</p>':'')+'<p>Alpen-Snake: Sammle zwölf Beeren. Wände und der eigene Körper beenden die Runde. Die Richtung wird mit Pfeilen/WASD oder den vier Touchknöpfen gewählt. Rückwärtsdrehen ist gesperrt.</p><p>Pong: Bewege deinen linken Schläger mit Pfeil hoch/runter, W/S, den Touchknöpfen oder durch Ziehen im Spielfeld. Wer zuerst fünf Punkte erzielt, gewinnt. Triff den Ball seitlich am Schläger, um seinen Winkel zu ändern.</p><p>Alpen-Breakout: Räume alle 32 Steine ab. Du hast drei Bälle. Steuere den unteren Schläger mit links/rechts, A/D, Touchknöpfen oder durch Ziehen im Spielfeld. Jeder Stein bringt zehn Punkte, ein verlorener Ball kostet zwanzig. Triff den Ball am Schlägerrand für einen anderen Winkel.</p><p>Alle Spiele sind gratis und kosten keine Energie. Drei Sekunden Countdown, höchstens 120 Sekunden pro Runde. Escape, P oder Pause hält an; dort kannst du abbrechen oder eine Spielstanddatei sichern. Neuladen setzt den gespeicherten Lauf fort.</p><p>'+(s.arcade.lampAwarded?'Die erste Höhlenlampe hast du bereits erhalten.':s.arcade.lampPending?'Deine Höhlenlampe wartet noch auf Abholung.':'Der erste Sieg in einem Retro-Spiel schenkt dir einmalig eine Höhlenlampe für Felsengang und Kristallgrotte.')+'</p>'+(s.arcade.lampPending?'<button id="arcade-lamp" class="primary">Höhlenlampe abholen</button>':'')+'<div class="item-grid">'+Object.entries(ARCADE_GAMES).map(([kind,g])=>'<article class="item-card"><h3>'+g.name+'</h3><p>'+g.goal+'</p>'+Object.entries(ARCADE_LEVELS).map(([level,l])=>'<p>'+l.name+' · Bestwert '+(s.arcade.best[kind+'-'+level]||0)+' · '+(s.arcade.runs[kind+'-'+level]||0)+' Runden</p><button data-retro="'+kind+'-'+level+'" '+(!atArcade(s)?'disabled':'')+'>Starten · '+l.name+'</button>').join('')+'</article>').join('')+'</div><p>'+(atArcade(s)?'Am Automaten bist du bereit.':'Gehe zum Automaten rechts im Laden, um eine Runde zu starten.')+'</p>');for(const el of document.querySelectorAll('[data-retro]'))el.onclick=()=>{captureState();const [kind,level]=el.dataset.retro.split('-'),r=startArcade(state,kind,level);if(!r.ok){showArcadeIntro(r.message);return;}arcRound=state.arcade.active;arcPaddleTarget=null;arcSaveTime=0;document.body.classList.add('arcading');closeDialog();syncArcade();save();};if(s.arcade.lampPending)$('arcade-lamp').onclick=()=>{captureState();const r=claimLamp(state,exchangeInventory);if(r.ok)save();showArcadeIntro(r.message);};}
function endArcade(){arcRound=null;arcPaddleTarget=null;arcTouch.clear();document.body.classList.remove('arcading');$('arcadehud').hidden=true;$('arcade-board').hidden=true;$('arcade-board').innerHTML='';updateNearest();}
function settleArcade(deferLamp=false){if(!arcRound?.done)return;const r=finishArcade(state,exchangeInventory,{deferLamp});if(!r.ok){dialog('<h2>Die Lampe braucht einen Platz</h2><p>'+r.message+'</p><p>Du kannst das Ergebnis jetzt sichern und die Lampe später am Automaten abholen.</p><button id="arcade-defer" class="primary">Ergebnis sichern · Lampe später abholen</button>');$('arcade-defer').onclick=()=>settleArcade(true);save();return;}endArcade();save();dialog('<span class="eyebrow">MELANIES RETRO-ECKE</span><h2 data-game-tone="'+(r.won?'success':'danger')+'">'+(r.won?'✓ ':'✕ ')+(r.won?'Melanie: «Sauber gspielt!»':'Melanie: «No es Ründli?»')+'</h2><p>'+ARCADE_GAMES[r.kind].name+' · '+ARCADE_LEVELS[r.level].name+' · '+r.score+' Punkte · '+r.time.toFixed(1)+' Sekunden</p><p>Bestwert: '+state.arcade.best[r.kind+'-'+r.level]+'. '+(r.lamp?'Deine erste Höhlenlampe liegt im Rucksack.':r.pending?'Deine erste Höhlenlampe wartet am Automaten, bis du Platz im Rucksack hast.':'Weitere Runden verbessern deinen Bestwert.')+'</p><div class="actions"><button id="arcade-again" class="primary">Zur Spielesammlung</button><button id="arcade-leave">Zurück in den Laden</button></div>');$('arcade-again').onclick=()=>showArcadeIntro();$('arcade-leave').onclick=closeDialog;}
function pauseArcade(){if(!arcRound)return;dialog('<span class="eyebrow">RETRO-PAUSE</span><h2>Alles steht still</h2><p>Zeit, Bälle und Schlange warten auf dich. Der aktuelle Stand bleibt beim Neuladen erhalten.</p><div class="actions"><button id="arcade-continue" class="primary">Weiterspielen</button><button id="arcade-abort">Abbrechen</button><button id="arcade-export">Spielstand herunterladen</button></div>');$('arcade-continue').onclick=closeDialog;$('arcade-abort').onclick=()=>{state.arcade.active=null;endArcade();closeDialog();save();};$('arcade-export').onclick=downloadSave;save();}
const arcTouch=new Set();for(const key of ['up','down','left','right']){const b=$('arcade-'+key);b.addEventListener('pointerdown',e=>{e.preventDefault();if(!arcRound||paused)return;if(arcRound.kind==='snake'){if(arcadeInput(arcRound,key))save();}else{arcPaddleTarget=null;arcTouch.add(key);}b.setPointerCapture?.(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>arcTouch.delete(key));}$('arcade-pause').onclick=pauseArcade;
function arcadePointer(e){if(!arcRound||paused||!['pong','breakout'].includes(arcRound.kind))return;const r=$('arcade-board').getBoundingClientRect(),w=r.right-r.left,h=r.bottom-r.top,scale=Math.min(w/480,h/320);if(!(scale>0))return;if(arcRound.kind==='breakout'){const left=r.left+(w-480*scale)/2;arcPaddleTarget=Math.max(44,Math.min(436,(e.clientX-left)/scale));}else{const top=r.top+(h-320*scale)/2;arcPaddleTarget=Math.max(32,Math.min(288,(e.clientY-top)/scale));}} $('arcade-board').addEventListener('pointerdown',e=>{e.preventDefault();arcadePointer(e);$('arcade-board').setPointerCapture?.(e.pointerId);});$('arcade-board').addEventListener('pointermove',e=>{if(e.buttons)arcadePointer(e);});
function mechanism(message=''){
 const known=state.adventure.discoveries.includes('cellar-note');dialog('<span class="eyebrow">DIE STEINTÜR</span><h2>Drei Räder. Ein alter Weg.</h2><p>'+(message||'Drehe die Steinräder und prüfe die Reihenfolge.')+'</p><div class="stone-dials">'+state.adventure.dials.map((v,i)=>'<button data-ring="'+i+'" aria-label="Steinrad '+(i+1)+' drehen"><span>'+['△','≈','✿'][v]+'</span><b>'+SYMBOLS[v]+'</b><small>Rad '+(i+1)+' · drehen</small></button>').join('')+'</div><p>'+(known?'Hinweis vom Regal: Erst das Wasser, dann die Blüte, zuletzt der Berg.':'Am alten Regal könnte ein Hinweis liegen.')+'</p><button id="unlock-door" class="primary">Steintür öffnen</button>');
 for(const el of document.querySelectorAll('[data-ring]'))el.onclick=()=>{turnDial(state,Number(el.dataset.ring));save();mechanism();};
 $('unlock-door').onclick=()=>{const result=openSecret(state);if(result.ok){save();closeDialog();toast(result.message);}else mechanism(result.message);};
}
