function updateQuest(){const herbCount=Math.min(3,state.herbs.length);$('herbcount').textContent=herbCount+' / 3';$('qhut').classList.toggle('done',state.hut);$('qride').classList.toggle('done',state.ride);$('qherbs').classList.toggle('done',herbCount>=3);$('qhut').textContent=(state.hut?'✓':'○')+' Die Alphütte besuchen';$('qride').textContent=(state.ride?'✓':'○')+' Mit Jonny den Parcours schaffen';let total=Number(state.hut)+Number(state.ride)+Number(herbCount>=3);$('questcompact').textContent=total+' / 3';$('progressbar').style.width=(total/3*100)+'%';$('progresslabel').textContent=total+' von 3 Entdeckungen · '+Math.round(total/3*100)+' %';for(const h of world.herbs)h.g.visible=state.gathered[h.id]!==state.day;for(const n of world.resources){if(n.syncResource)n.syncResource(state);else n.g.visible=resourceReady(state,n);}world.sync?.(state);world.farmKit?.sync(state);world.homeKit?.sync(state);world.estateKit?.sync(state);world.seasonalKit?.sync(state);world.lifeKit?.sync(state);world.cozyKit?.sync(state);headLamp.visible=!!state.inventory.lamp&&['passage','kristall'].includes(region)||!!state.inventory.lantern&&environmentLight(state.environment).night>.05;$('qfarm').textContent='Tiere versorgt: '+Object.keys(ANIMALS).filter(id=>{const a=state.farm.animals[id];return a.feedDay===state.day&&a.waterDay===state.day&&a.careDay===state.day;}).length+' / '+Object.keys(ANIMALS).length;$('qvillage').textContent='Dorfaufträge: '+state.village.completed.length+' / '+ORDERS.length;$('qclimbs').textContent='Kletterrouten geschafft: '+state.climbing.completed.length+' / 3';$('qexpedition').textContent='Berggebiete entdeckt: '+ADVENTURE_REGIONS.filter(k=>state.adventure.visited.includes(k)).length+' / 8';updateVitals();}
function tone(freq=440,dur=.1,type='sine',gain=.1){if(!soundEnabled||!ac||ac.state!=='running')return;const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,ac.currentTime);g.gain.setValueAtTime(gain*volume,ac.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+dur);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+dur);}
function unlock(){if(!ac){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio)ac=new Audio();}ac?.resume();syncAudio();}
function footstep(riding=false){if(!soundEnabled||!ac||ac.state!=='running')return;const len=.055,buffer=ac.createBuffer(1,Math.floor(ac.sampleRate*len),ac.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.exp(-i/d.length*7);const n=ac.createBufferSource();n.buffer=buffer;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=riding?850:420;const g=ac.createGain();g.gain.value=volume*(riding?.36:.19);n.connect(f).connect(g).connect(ac.destination);n.start();}
function leaveMinigame(){keys.clear();if(course){closeDialog();endRide();return;}if(ski){abandonSki(state);endSkiRuntime();}if(targetRound){state.targets.active=null;endTargetRuntime();}if(arcRound){state.arcade.active=null;endArcade();}if(climb){closeDialog();endClimbRuntime(false);return;}if(state.jass.active)state.jass.active=null;closeDialog();save();}
