function bindCharacterPicker(refresh){document.querySelectorAll('[data-avatar]').forEach(button=>{button.disabled=!!(course||climb||ski||targetRound||arcRound);button.onclick=()=>{if(course||climb||ski||targetRound||arcRound)return;player.setAppearance(button.dataset.avatar);headLamp.position.y=player.height-.15;syncHome();save();refresh();};});}
function welcome(){dialog('<span class="eyebrow">WILLKOMMEN AUF DER PORTMANN-ALP</span><h2>Portmann Alp</h2><p class="game-subtitle">Chäs, Fondue und Alpenluft</p>'+(cloudPanels?cloudPanels.overview()+'<button id="welcome-save">Spielstand & Konto ansehen</button>':'')+characterPickerMarkup()+'<p>Entdecke die Portmann-Alp: eine Schweizer Bergwelt mit Hütte, Blumenwiesen und Jonny. Dies ist der aktuelle Entwicklungsstand des vollständigen Adventures.</p><p>Tippe oder klicke auf die Wiese, um ein Ziel zu wählen. Auf iPhone und iPad kannst du den Finger auf der Spielfläche in die gewünschte Richtung ziehen und halten; Loslassen stoppt die Figur. Tippe auf die Alphütte oder einen Wegweiser: Du gehst zum Eingang und betrittst ihn automatisch. Die drei ersten Entdeckungen sind freiwillige Ziele und sperren keine Wege. Am Mac kannst du auch mit WASD oder den Pfeiltasten laufen. In der Nähe von Hütte, Kräutern und Jonny erscheint die passende Aktion.</p><p>Über Rucksack, Rezeptbuch und Aufgabenbuch planst du deine Tour. In der Hütte kannst du kostenlos rasten, schlafen, herstellen und lagern. Am Dorfladen findest du Vorräte und eine Spitzhacke.</p><p>Der Panoramaweg im Norden führt frei zur Hochalp und zum Gipfel; der Talweg im Osten führt bergab zum Dorf und weiter in die Stadt. Im Süden erreichst du das Dorf auch direkt. Jonnys Reitweide hat ihren eigenen Zugang im Südosten. Im Dorfhaus gelangst du über den Keller und seine Steintür zu den geheimen Bergwegen.</p><p>Beim Parcours läuft Jonny selbst. Du übernimmst die Sprünge: Leertaste oder «Springen».</p><div class="actions"><button class="primary" id="begin">Die Alp entdecken</button></div><small>'+saveStore.status.message+' Rucksack, 38 Rezepte, Dorfladen und Aufgabenbuch stehen bereit. Dorfhaus, Kellerrätsel und acht verbundene Berggebiete sind zugänglich. Im Dorf warten Anna, Sepp, Ruth und Dani mit Gesprächen und sechs verbundenen Aufträgen. Weitere Aktivitäten werden ausgebaut.</small>');$('begin').onclick=()=>{unlock();closeDialog();save();if(state.jass.active)jassPanels.game();else if(state.activities.active)openCozy(state.activities.active.kind);};if($('welcome-save'))$('welcome-save').onclick=()=>cloudPanels.open();bindCharacterPicker(welcome);}
function interact(){if(arcRound){pauseArcade();return;}if(state.jass.active){jassPanels.game();return;}if(targetRound){pauseTarget();return;}if(ski){pauseSki();return;}if(climb){pauseClimb();return;}if(inside){const n=nearestHome();if(n)doHomeAction(n.id);return;}if(course){if(course.done){finishRide();return;}if(!course.done){dialog('<span class="eyebrow">JONNYS PARCOURS</span><h2>Eine Pause machen?</h2><p>Die laufende Runde wird dabei beendet. Dein bisheriger Bestwert bleibt erhalten.</p><div class="actions"><button id="continue" class="primary">Weiterreiten</button><button id="stopride">Runde beenden</button></div>');$('continue').onclick=closeDialog;$('stopride').onclick=()=>{closeDialog();endRide();};}return;}if(!nearest)return;
const n=nearest;if(n.shopCategory){captureState();panels.shop('',n.shopCategory);return;}if(n.villageFountain){captureState();const r=exchangeInventory(state,{give:{water:1}});if(r.ok){state.survival.thirst=100;save();}toast(r.ok?'Frisches Quellwasser eingepackt · Durst gestillt.':r.message);return;}if(n.woodDepot){showWoodDepot();return;}if(n.hutSleep){captureState();const r=rest(state,true,true);if(r.ok)save();toast(r.message);return;}if(n.mountainGuide){dialog('<span class="eyebrow">BERGFÜHRER DANIEL</span><h2>Grüezi, ich bin Daniel.</h2><p>Meine Tourenhütte steht auf der breiten Gipfelschulter. Drinnen kannst du übernachten, bevor du über den Adlergrat oder die Sonnenalp zurückwanderst.</p><p>Prüfe Wetter, Energie und Ausrüstung. Bei Dunkelheit helfen Laterne und ein sicherer Schlafplatz. Die normalen Wanderwege bleiben ohne Kletterausrüstung begehbar.</p>');return;}if(n.downhill){openDownhill();return;}if(n.villageService){captureState();if(n.villageService==='doctor'){const r=rest(state,false,true);if(r.ok)save();dialog('<span class="eyebrow">DORFPRAXIS</span><h2>Eine kleine Verschnaufpause</h2><p>'+r.message+'</p><p>Die Dorfpraxis versorgt Wandernde kostenlos. Deine Energie beträgt '+Math.round(state.energy)+' / 100.</p>');}else panels.shop('',n.villageService==='bakery'?['bread','berryBread','oatMilk','veganMeal']:['pumpkin','christmasTree','autumnDecor','halloweenDecor','christmasDecor','oatMilk','veganMeal','apple','nuts']);return;}if(n.estateBusiness){estatePanels.business();return;}if(n.cozyActivity){openCozy(n.cozyActivity);return;}if(n.forestDiscovery){captureState();if(!state.activities.discoveries.includes(n.forestDiscovery)){state.activities.discoveries.push(n.forestDiscovery);save();}toast('Eine stille Waldlichtung entdeckt. Die Belohnung wartet im Aufgabenbuch.');return;}if(n.hayStorage){lifePanels.shelter();return;}if(n.hayField){lifePanels.field();return;}if(n.pondCamp){lifePanels.camp();return;}if(n.fodderShop){captureState();panels.shop();return;}if(n.barnDoor){const goal={x:1.5,z:-12};path=route(pos,goal,world.colliders);navigationGoal=null;marker.visible=false;overview=false;toast('Du gehst durch das offene Stalltor.');return;}if(n.portmannStore){dairyPanels.store();return;}if(n.scenic){toast('Ein freier Weg. Keine Uhr, kein Einsatz: Weiter bergwärts zur Hochalp oder zurück zu deiner Hütte.');return;}if(n.estateField){estatePanels.field(n.estateField);return;}if(n.estateFire){estatePanels.fire();return;}if(n.valleyView){openPanorama();return;}if(n.arcade){showArcadeIntro();return;}if(n.melanie){dialog('<span class="eyebrow">MELANIES LADEN</span><h2>Melanie</h2><p>«Grüezi! Du chasch gratis spiele. Rechts am Automat git’s Snake, Pong und Breakout. De erscht Sieg bringt dir e Höhlelampe. Und wenn’s nöd klappt: Revanche koschtet nüt.»</p><button id="melanie-games" class="primary">Spielesammlung ansehen</button>');$('melanie-games').onclick=()=>showArcadeIntro();return;}if(n.jass){jassPanels.intro();return;}if(n.meal){jassPanels.menu();return;}if(n.targetGame){showTargetIntro(n.targetGame);return;}if(n.ski){showSkiIntro();return;}if(n.npc){captureState();villagePanels.conversation(n.npc);return;}if(n.animal){farmPanels.animal(n.animal);return;}if(n.farmSupply){farmPanels.supply(n.farmSupply);return;}if(n.climbRoute){showClimbIntro(n.climbRoute);return;}if(n.gateway){enterGateway(n);return;}if(n.note){discover(state,'cellar-note');save();dialog('<span class="eyebrow">EIN VERGESSENER HINWEIS</span><h2>Die drei Zeichen</h2><p>Auf einem vergilbten Blatt steht: Erst das Wasser, dann die Blüte, zuletzt der Berg.</p><p>Drei Steinräder sitzen vor der zugemauerten Tür. Vielleicht lässt sich der alte Weg wieder öffnen.</p>');return;}if(n.dial!==undefined){mechanism();return;}if(n.landmark){discover(state,n.id.replace('landmark-',''));save();dialog('<span class="eyebrow">ENTDECKUNG</span>'+(['panorama','summit'].includes(region)?'<img src="assets/portmann/swiss-ridge-20261018.webp" alt="Schweizer Kalksteingrate und Berner Alpen als Landschaftsvorlage" style="width:100%;border-radius:14px">':'')+'<h2>'+n.title+'</h2><p>'+n.text+'</p><small>Im Aufgabenbuch und im Spielstand festgehalten.</small>');return;}if(n.treasure){captureState();const result=claimTreasure(state,n.id);if(result.ok)save();toast(result.message);return;}if(n.id==='hut'){inside=true;state.home.floor='stube';state.home.x=0;state.home.z=3.25;homePath=[];homeGoal=null;syncHome();snapInteriorCamera();syncAudio();state.hut=true;const saved=save();path=[];marker.visible=false;player.g.visible=true;$('place').textContent='Ein warmes Plätzchen.';$('subtitle').textContent='Rucksack öffnen: lagern, rasten und herstellen.';updateNearest();toast(saved.ok?'Alphütte entdeckt · Fortschritt auf diesem Gerät gespeichert.':'Alphütte entdeckt · Gerätespeicherung fehlgeschlagen. Bitte sichere eine Spielstanddatei.');}
else if(n.id==='horse'||n.id==='course'){dialog('<span class="eyebrow">JONNY · DEIN ALPPFERD</span><h2>Bereit für eine Runde?</h2><p>«Ich habe vier Balken gezählt. Du hoffentlich auch.»</p><p>Jonny läuft gerade durch den Parcours. Springe etwa <strong>bei der goldenen Bodenmarkierung vor dem Balken</strong>. Jeder freie Sprung bringt 100 Punkte. Eine Berührung kostet 50 Punkte und zählt als Fehler.</p><p>Auf Einfach reichen <strong>drei von vier Sprüngen</strong> für die Aufgabe. Sportlich und Profi verlangen vier freie Sprünge. Du kannst beliebig oft üben.</p><div class="actions"><label>Schwierigkeit <select id="ride-level"><option value="easy">Einfach · 3 von 4</option><option value="normal">Sportlich · 4 von 4</option><option value="hard">Profi · 4 von 4</option></select></label><button class="primary" id="startride">Aufsitzen & starten</button><button id="pet">Jonny streicheln</button><button id="horse-care">Jonny versorgen</button></div>');$('startride').onclick=()=>{const level=$('ride-level').value||'easy';closeDialog();startRide(level);};$('horse-care').onclick=()=>farmPanels.animal('jonny');$('pet').onclick=()=>{closeDialog();toast('Jonny schnaubt zufrieden. «Erst streicheln, dann Höchstleistung. Guter Plan.»');};}
else if(n.resource||n.id.startsWith('herb')){const node=n.resource?n:{id:n.id,item:'herb',amount:1,energy:2};const result=collect(state,node);if(!result.ok){toast(result.message);return;}if(n.index!==undefined&&!state.herbs.includes(n.index))state.herbs.push(n.index);save();updateNearest();tone(740,.18,'sine',.13);setTimeout(()=>tone(990,.2,'sine',.1),90);toast(result.message);}
else if(n.id==='shop')panels.shop();
else if(n.id==='lookout'){openPanorama();}}
function showWoodDepot(message=''){captureState();dialog('<span class="eyebrow">HOLZPLATZ NEBEN DER ALPHÜTTE</span><h2>Beil & Holzvorrat</h2><p>'+message+'</p><p>Fallholz erscheint nach einer Nacht erneut. Die gelb markierten Nutzbäume liefern mit dem Beil je vier Holz und wachsen nach drei Nächten nach. Den übrigen Wald lassen wir stehen.</p><p>Rucksack: '+(state.inventory.wood||0)+' Holz · Lager: '+(state.storage.wood||0)+' Holz</p><button id="wood-axe" '+(state.activities.discoveries.includes('alp-axe')?'disabled':'')+'>Beil mitnehmen · einmal kostenlos</button><button id="wood-store">Ein Holz einlagern</button><button id="wood-take">Ein Holz einpacken</button>');$('wood-axe').onclick=()=>{const r=takeAlpAxe(state);if(r.ok)save();showWoodDepot(r.message);};for(const[id,toChest]of [['wood-store',true],['wood-take',false]])$(id).onclick=()=>{const r=transfer(state,'wood',toChest,true);if(r.ok)save();showWoodDepot(r.message);};}
