window.addEventListener('keydown',e=>{if(paused||e.target.matches('input,textarea,select,[contenteditable=true]'))return;if(arcRound){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(['Escape','KeyP','Space'].includes(e.code)&&!e.repeat){pauseArcade();return;}const dir={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'}[e.code];if(arcRound.kind==='snake'){if(dir&&!e.repeat&&arcadeInput(arcRound,dir))save();}else{arcPaddleTarget=null;keys.add(e.code);}return;}if(targetRound){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','KeyE','Escape'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&!e.repeat){pauseTarget();return;}if(['KeyE','Space'].includes(e.code)&&!e.repeat){fireTarget();return;}keys.add(e.code);return;}if(ski){if(['ArrowLeft','ArrowRight','ArrowDown','Space','KeyA','KeyD','KeyS','KeyE','Escape'].includes(e.code))e.preventDefault();if(['KeyE','Escape','Space'].includes(e.code)&&!e.repeat){pauseSki();return;}keys.add(e.code);return;}if(climb){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter','Space','KeyE'].includes(e.code))e.preventDefault();if(e.repeat)return;const opts=choices(climb);if(e.code==='ArrowLeft'||e.code==='ArrowRight'){climb.selected=(climb.selected+(e.code==='ArrowRight'?1:-1)+Math.max(1,opts.length))%Math.max(1,opts.length);syncClimbHUD();}else if(['Enter','Space','ArrowUp'].includes(e.code)&&opts.length)takeGrip(opts[climb.selected]);else if(e.code==='ArrowDown')$('climb-rest').onclick();else if(e.code==='KeyE')pauseClimb();else if(/^Digit[1-9]$/.test(e.code))takeGrip(Number(e.code.slice(-1))-1);return;}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(paused)return;unlock();if(e.code==='KeyE'&&!e.repeat)interact();if(e.code==='Space'&&!e.repeat)jump();keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearWorldTap();keys.clear();skiTouch.clear();targetTouch.clear();if(arcRound)pauseArcade();else if(targetRound)pauseTarget();else if(ski)pauseSki();else save();});window.addEventListener('pagehide',()=>save());document.addEventListener('visibilitychange',()=>{clearWorldTap();keys.clear();clock.getDelta();if(document.hidden){skiTouch.clear();targetTouch.clear();if(arcRound)pauseArcade();else if(targetRound)pauseTarget();else if(ski)pauseSki();else save();ac?.suspend();music.pause();birds.pause();}else{if(ac)ac.resume();if(!paused)syncAudio();}});
